import java.net.URLClassLoader;
import java.util.Random;

/** Differential test for UPC/EAN extension decoders: original vs refactored decodeRow. */
public final class ExtDiff {

  static URLClassLoader loader(String dir) throws Exception {
    return new URLClassLoader(new URL[]{ new File(dir).toURI().toURL() }, null);
  }

  /** Build a BitArray of given size from a boolean[] via reflection, so both classloaders get their own type. */
  static Object makeBitArray(ClassLoader cl, boolean[] bits) throws Exception {
    Class<?> ba = Class.forName("com.google.zxing.common.BitArray", true, cl);
    Object inst = ba.getConstructor(int.class).newInstance(bits.length);
    Method set = ba.getMethod("set", int.class);
    for (int i = 0; i < bits.length; i++) {
      if (bits[i]) {
        set.invoke(inst, i);
      }
    }
    return inst;
  }

  /** Returns a canonical signature of the decodeRow outcome: exception or Result contents. */
  static String run(ClassLoader cl, String className, boolean[] bits, int rowNumber, int[] range) {
    try {
      Class<?> support = Class.forName("com.google.zxing.oned." + className, true, cl);
      Object inst = support.getDeclaredConstructor().newInstance();
      Class<?> ba = Class.forName("com.google.zxing.common.BitArray", true, cl);
      Method decodeRow = support.getDeclaredMethod("decodeRow", int.class, ba, int[].class);
      decodeRow.setAccessible(true);
      Object row = makeBitArray(cl, bits);
      Object result = decodeRow.invoke(inst, rowNumber, row, range);

      Class<?> resultClass = Class.forName("com.google.zxing.Result", true, cl);
      String text = (String) resultClass.getMethod("getText").invoke(result);
      Object pts = resultClass.getMethod("getResultPoints").invoke(result);
      Object meta = resultClass.getMethod("getResultMetadata").invoke(result);
      StringBuilder sb = new StringBuilder("OK|text=").append(text).append("|pts=");
      int n = java.lang.reflect.Array.getLength(pts);
      for (int i = 0; i < n; i++) {
        Object p = java.lang.reflect.Array.get(pts, i);
        float x = (float) p.getClass().getMethod("getX").invoke(p);
        float y = (float) p.getClass().getMethod("getY").invoke(p);
        sb.append('(').append(x).append(',').append(y).append(')');
      }
      sb.append("|meta=").append(meta == null ? "null" : meta.toString());
      return sb.toString();
    } catch (Throwable t) {
      Throwable c = (t.getCause() != null) ? t.getCause() : t;
      return "EX|" + c.getClass().getName();
    }
  }

  public static void main(String[] args) throws Exception {
    ClassLoader oldCl = loader(args[0]);
    ClassLoader newCl = loader(args[1]);
    String[] classes = { "UPCEANExtension2Support", "UPCEANExtension5Support" };

    Random r = new Random(123);
    int total = 0;
    int mismatches = 0;
    int okCount = 0;
    for (int iter = 0; iter < 200000; iter++) {
      int size = 40 + r.nextInt(80);
      boolean[] bits = new boolean[size];
      for (int i = 0; i < size; i++) {
        bits[i] = r.nextBoolean();
      }
      int a = r.nextInt(size / 2);
      int b = a + 1 + r.nextInt(5); // extensionStartRange = [a, b]; decodeMiddle starts at b
      int[] range = { a, b };
      int rowNumber = r.nextInt(500);
      for (String cls : classes) {
        total++;
        String oldOut = run(oldCl, cls, bits, rowNumber, range);
        String newOut = run(newCl, cls, bits, rowNumber, range);
        if (oldOut.startsWith("OK")) {
          okCount++;
        }
        if (!oldOut.equals(newOut)) {
          mismatches++;
          if (mismatches <= 20) {
            System.out.println("MISMATCH " + cls + " range=[" + a + "," + b + "] size=" + size);
            System.out.println("  old: " + oldOut);
            System.out.println("  new: " + newOut);
          }
        }
      }
    }
    System.out.println("----");
    System.out.println("Total comparisons:    " + total);
    System.out.println("Success-path results: " + okCount + " (both branches exercised)");
    System.out.println("Mismatches:           " + mismatches);
    System.out.println(mismatches == 0 ? "RESULT: IDENTICAL BEHAVIOR" : "RESULT: DIFFERENCES FOUND");
  }
}

