import java.io.File;
import java.lang.reflect.Array;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.ArrayList;
import java.util.List;

/** Builds genuinely valid UPC/EAN extension rows and diffs original vs refactored decodeRow. */
public final class ExtValid {

  // L patterns (space,bar,space,bar widths), digit 0..9. G pattern = reverse of L.
  static final int[][] L = {
      {3,2,1,1},{2,2,2,1},{2,1,2,2},{1,4,1,1},{1,1,3,2},
      {1,2,3,1},{1,1,1,4},{1,3,1,2},{1,2,1,3},{3,1,1,2}
  };

  static int[] g(int d) {
    int[] l = L[d];
    return new int[]{ l[3], l[2], l[1], l[0] };
  }

  /** Appends alternating runs starting with the given color. */
  static void addRuns(List<Boolean> row, boolean startColor, int[] widths) {
    boolean color = startColor;
    for (int w : widths) {
      for (int i = 0; i < w; i++) {
        row.add(color);
      }
      color = !color;
    }
  }

  /**
   * Builds a row for an extension. digits[] are the digit values; useG[] whether each is a G pattern.
   * Layout: start padding (b whites) | digit | (sep) | digit | ... ; separator = white,black,white so
   * getNextSet/getNextUnset lands at next digit. Returns the boolean[] plus sets range in range[].
   */
  static boolean[] build(int b, int[] digits, boolean[] useG) {
    List<Boolean> row = new ArrayList<>();
    for (int i = 0; i < b; i++) {
      row.add(false); // leading whites (start guard region; unused by decodeMiddle except index b)
    }
    for (int x = 0; x < digits.length; x++) {
      int[] widths = useG[x] ? g(digits[x]) : L[digits[x]];
      addRuns(row, false, widths); // each digit starts white
      if (x != digits.length - 1) {
        // separator: a white gap, a black bar, then the next digit begins (white)
        row.add(false); // white gap  (row currently ends black -> this starts a white run)
        row.add(true);  // black separator bar
        // next digit's leading white follows
      } else {
        row.add(false); // trailing white so last black run has finite width
      }
    }
    for (int i = 0; i < 10; i++) {
      row.add(false); // trailing padding
    }
    boolean[] out = new boolean[row.size()];
    for (int i = 0; i < out.length; i++) {
      out[i] = row.get(i);
    }
    return out;
  }

  static Object makeBitArray(ClassLoader cl, boolean[] bits) throws Exception {
    Class<?> ba = Class.forName("com.google.zxing.common.BitArray", true, cl);
    Object inst = ba.getConstructor(int.class).newInstance(bits.length);
    Method set = ba.getMethod("set", int.class);
    for (int i = 0; i < bits.length; i++) {
      if (bits[i]) {
        set.invoke(inst, i);
      }
    }
    return inst;
  }

  static String run(ClassLoader cl, String className, boolean[] bits, int rowNumber, int[] range) {
    try {
      Class<?> support = Class.forName("com.google.zxing.oned." + className, true, cl);
      Object inst = support.getDeclaredConstructor().newInstance();
      Class<?> ba = Class.forName("com.google.zxing.common.BitArray", true, cl);
      Method decodeRow = support.getDeclaredMethod("decodeRow", int.class, ba, int[].class);
      decodeRow.setAccessible(true);
      Object result = decodeRow.invoke(inst, rowNumber, makeBitArray(cl, bits), range);
      Class<?> rc = Class.forName("com.google.zxing.Result", true, cl);
      String text = (String) rc.getMethod("getText").invoke(result);
      Object pts = rc.getMethod("getResultPoints").invoke(result);
      Object meta = rc.getMethod("getResultMetadata").invoke(result);
      StringBuilder sb = new StringBuilder("OK|text=").append(text).append("|pts=");
      int n = Array.getLength(pts);
      for (int i = 0; i < n; i++) {
        Object p = Array.get(pts, i);
        sb.append('(').append(p.getClass().getMethod("getX").invoke(p)).append(',')
          .append(p.getClass().getMethod("getY").invoke(p)).append(')');
      }
      sb.append("|meta=").append(meta == null ? "null" : meta.toString());
      return sb.toString();
    } catch (Throwable t) {
      Throwable c = (t.getCause() != null) ? t.getCause() : t;
      return "EX|" + c.getClass().getName();
    }
  }

  static URLClassLoader loader(String dir) throws Exception {
    return new URLClassLoader(new URL[]{ new File(dir).toURI().toURL() }, null);
  }

  public static void main(String[] args) throws Exception {
    ClassLoader oldCl = loader(args[0]);
    ClassLoader newCl = loader(args[1]);
    int b = 10;

    List<Object[]> cases = new ArrayList<>();
    // 2-digit cases: all 100 values, L/G parity chosen to satisfy value%4 == checkParity.
    for (int v = 0; v < 100; v++) {
      int d0 = v / 10;
      int d1 = v % 10;
      int target = v % 4; // need checkParity == target; checkParity bit1=digit0 isG, bit0=digit1 isG
      boolean g0 = (target & 2) != 0;
      boolean g1 = (target & 1) != 0;
      cases.add(new Object[]{ "UPCEANExtension2Support", new int[]{d0, d1}, new boolean[]{g0, g1} });
    }
    // 5-digit cases: for each check digit value, use its CHECK_DIGIT_ENCODINGS parity and digits that checksum to it.
    int[] CHECK = { 0x18,0x14,0x12,0x11,0x0C,0x06,0x03,0x0A,0x09,0x05 };
    // enumerate digit strings and bucket by extensionChecksum, pick first per check digit
    int[][] chosen = new int[10][];
    for (int v = 0; v < 100000 && hasNull(chosen); v++) {
      int[] ds = new int[5];
      int t = v;
      for (int i = 4; i >= 0; i--) { ds[i] = t % 10; t /= 10; }
      int cd = extChecksum(ds);
      if (chosen[cd] == null) {
        chosen[cd] = ds;
      }
    }
    for (int cd = 0; cd < 10; cd++) {
      int[] ds = chosen[cd];
      int enc = CHECK[cd];
      boolean[] useG = new boolean[5];
      for (int x = 0; x < 5; x++) {
        useG[x] = (enc & (1 << (4 - x))) != 0;
      }
      cases.add(new Object[]{ "UPCEANExtension5Support", ds, useG });
    }

    int total = 0;
    int ok = 0;
    int mism = 0;
    for (Object[] c : cases) {
      String cls = (String) c[0];
      int[] ds = (int[]) c[1];
      boolean[] useG = (boolean[]) c[2];
      boolean[] bits = build(b, ds, useG);
      int[] range = { 4, b };
      int rowNumber = 17;
      String o = run(oldCl, cls, bits, rowNumber, range);
      String n = run(newCl, cls, bits, rowNumber, range);
      total++;
      if (o.startsWith("OK")) {
        ok++;
      }
      if (!o.equals(n)) {
        mism++;
        if (mism <= 20) {
          System.out.println("MISMATCH " + cls + " digits=" + java.util.Arrays.toString(ds));
          System.out.println("  old: " + o);
          System.out.println("  new: " + n);
        }
      } else if (o.startsWith("OK") && ok <= 4) {
        System.out.println("sample OK " + cls + " digits=" + java.util.Arrays.toString(ds) + " -> " + o);
      }
    }
    System.out.println("----");
    System.out.println("Constructed cases:    " + total);
    System.out.println("Success-path results: " + ok);
    System.out.println("Mismatches:           " + mism);
    System.out.println(mism == 0 ? "RESULT: IDENTICAL BEHAVIOR" : "RESULT: DIFFERENCES FOUND");
  }

  static boolean hasNull(int[][] a) {
    for (int[] x : a) {
      if (x == null) {
        return true;
      }
    }
    return false;
  }

  static int extChecksum(int[] ds) {
    int length = ds.length;
    int sum = 0;
    for (int i = length - 2; i >= 0; i -= 2) {
      sum += ds[i];
    }
    sum *= 3;
    for (int i = length - 1; i >= 0; i -= 2) {
      sum += ds[i];
    }
    sum *= 3;
    return sum % 10;
  }
}

