import java.net.URL;
import java.net.URLClassLoader;
import java.util.ArrayList;
import java.util.List;

public final class Dbg {
  static final int[][] L = {
      {3,2,1,1},{2,2,2,1},{2,1,2,2},{1,4,1,1},{1,1,3,2},
      {1,2,3,1},{1,1,1,4},{1,3,1,2},{1,2,1,3},{3,1,1,2}
  };
  public static void main(String[] args) throws Exception {
    URLClassLoader cl = new URLClassLoader(new URL[]{ new File(args[0]).toURI().toURL() }, null);
    int b = 10;
    List<Boolean> row = new ArrayList<>();
    for (int i = 0; i < b; i++) row.add(false);
    // digit0 '0' L
    addRuns(row, false, L[0]);
    // separator: white gap, black bar
    row.add(false); row.add(true);
    // digit1 '0' L
    addRuns(row, false, L[0]);
    row.add(false);
    for (int i = 0; i < 10; i++) row.add(false);

    StringBuilder vis = new StringBuilder();
    for (boolean bit : row) vis.append(bit ? '1' : '0');
    System.out.println("row: " + vis + " (size " + row.size() + ")");

    Class<?> ba = Class.forName("com.google.zxing.common.BitArray", true, cl);
    Object rowObj = ba.getConstructor(int.class).newInstance(row.size());
    Method set = ba.getMethod("set", int.class);
    for (int i = 0; i < row.size(); i++) if (row.get(i)) set.invoke(rowObj, i);

    Class<?> support = Class.forName("com.google.zxing.oned.UPCEANExtension2Support", true, cl);
    Object inst = support.getDeclaredConstructor().newInstance();
    Method decodeRow = support.getDeclaredMethod("decodeRow", int.class, ba, int[].class);
    decodeRow.setAccessible(true);
    try {
      Object result = decodeRow.invoke(inst, 17, rowObj, new int[]{4, b});
      System.out.println("SUCCESS: " + result.getClass().getMethod("getText").invoke(result));
    } catch (Throwable t) {
      Throwable c = t.getCause() != null ? t.getCause() : t;
      System.out.println("THREW: " + c);
      c.printStackTrace();
    }
  }
  static void addRuns(List<Boolean> row, boolean startColor, int[] widths) {
    boolean color = startColor;
    for (int w : widths) { for (int i = 0; i < w; i++) row.add(color); color = !color; }
  }
}

